import { readFrozenSpecificationBody, readStagedJson, writeStagedJson } from './run-store.js';

export type RequirementKind = 'FR' | 'NFR' | 'AC' | 'INV';

export interface TraceEntry {
  id: string;
  kind: RequirementKind;
  source: string;
}

export interface TraceArtifact {
  entries: TraceEntry[];
}

export interface RequirementSource {
  kind: RequirementKind;
  source: string;
}

const KINDS: readonly RequirementKind[] = ['FR', 'NFR', 'AC', 'INV'];

function idNumber(id: string): number {
  const m = /-(\d+)$/.exec(id);
  return m ? Number(m[1]) : 0;
}

export function carryForwardIds(
  current: RequirementSource[],
  previous: TraceArtifact | null,
): TraceArtifact {
  const priorBySource = new Map<string, string>();
  const maxByKind = new Map<RequirementKind, number>();
  for (const kind of KINDS) maxByKind.set(kind, 0);

  for (const entry of previous?.entries ?? []) {
    priorBySource.set(`${entry.kind}�${entry.source}`, entry.id);
    const n = idNumber(entry.id);
    if (n > (maxByKind.get(entry.kind) ?? 0)) {
      maxByKind.set(entry.kind, n);
    }
  }

  const entries: TraceEntry[] = [];
  for (const req of current) {
    const key = `${req.kind}�${req.source}`;
    const inherited = priorBySource.get(key);
    if (inherited !== undefined) {
      entries.push({ id: inherited, kind: req.kind, source: req.source });
      continue;
    }
    const next = (maxByKind.get(req.kind) ?? 0) + 1;
    maxByKind.set(req.kind, next);
    entries.push({ id: `${req.kind}-${next}`, kind: req.kind, source: req.source });
  }
  return { entries };
}

export interface TraceValidation {
  ok: boolean;
  unsourced: string[];
}

export function validateTrace(trace: TraceArtifact): TraceValidation {
  const unsourced = trace.entries
    .filter((e) => typeof e.source !== 'string' || e.source.trim().length === 0)
    .map((e) => e.id);
  return { ok: unsourced.length === 0, unsourced };
}

export function extractRequirementIds(markdown: string): string[] {
  const ids = new Set<string>();
  const re = /\b((?:FR|NFR|AC|INV)-\d+)\b/g;
  let m: RegExpExecArray | null;
  while ((m = re.exec(markdown)) !== null) ids.add(m[1]!);
  return [...ids];
}

export interface CraftTraceValidation {
  ok: boolean;
  errors: string[];
}

export function validateCraftTrace(
  specMarkdown: string,
  trace: TraceArtifact,
  acceptedFindingIds: readonly string[] = [],
): CraftTraceValidation {
  const errors: string[] = [];

  const unsourced = validateTrace(trace);
  for (const id of unsourced.unsourced) {
    errors.push(
      `line "${id}" has no source; every requirement must trace to the task, an answer, or an expert finding`,
    );
  }

  const tracedIds = new Set(trace.entries.map((entry) => entry.id));
  for (const id of extractRequirementIds(specMarkdown)) {
    if (!tracedIds.has(id)) {
      errors.push(
        `line "${id}" has no source; every requirement must trace to the task, an answer, or an expert finding`,
      );
    }
  }

  const tracedSources = new Set(trace.entries.map((entry) => entry.source));
  const unreflected = acceptedFindingIds.filter((id) => !tracedSources.has(id));
  if (unreflected.length > 0) {
    errors.push(`accepted expert findings not reflected in the spec: ${unreflected.join(', ')}`);
  }

  return { ok: errors.length === 0, errors };
}

export function writeTrace(projectRoot: string, dirName: string, trace: TraceArtifact): void {
  writeStagedJson(projectRoot, dirName, 'trace', trace);
}

export function readTrace(projectRoot: string, dirName: string): TraceArtifact | null {
  const parsed = readStagedJson<TraceArtifact>(projectRoot, dirName, 'trace');
  if (parsed !== null && Array.isArray(parsed.entries)) return parsed;
  const frozen = readFrozenSpecificationBody(projectRoot, dirName);
  const map = frozen?.trace;
  if (typeof map === 'object' && map !== null && !Array.isArray(map)) {
    return traceFromMap(map as Record<string, unknown>);
  }
  const legacy = (frozen?.provenance as { trace?: TraceArtifact } | undefined)?.trace;
  return legacy !== undefined && Array.isArray(legacy.entries) ? legacy : null;
}

function traceFromMap(map: Record<string, unknown>): TraceArtifact {
  const entries: TraceEntry[] = [];
  for (const [id, source] of Object.entries(map)) {
    const kind = kindOf(id);
    if (kind !== null && typeof source === 'string') entries.push({ id, kind, source });
  }
  return { entries };
}

function kindOf(id: string): RequirementKind | null {
  const prefix = id.split('-')[0] as RequirementKind;
  return KINDS.includes(prefix) ? prefix : null;
}

export function parseTraceArtifact(raw: unknown): TraceArtifact | null {
  if (typeof raw !== 'object' || raw === null) return null;
  const entries = (raw as Record<string, unknown>).entries;
  if (!Array.isArray(entries)) return null;
  const out: TraceEntry[] = [];
  for (const entry of entries) {
    if (typeof entry !== 'object' || entry === null) return null;
    const { id, source } = entry as Record<string, unknown>;
    if (typeof id !== 'string' || typeof source !== 'string') return null;
    const kind = kindOf(id);
    if (kind === null) return null;
    out.push({ id, kind, source });
  }
  return { entries: out };
}
